{"task": "Find all log entries containing version strings in messages", "sql": "SELECT * FROM logs WHERE regexp_like(message, 'v[0-9]+\\.[0-9]+\\.[0-9]+')"}
{"task": "Count error logs that mention version numbers", "sql": "SELECT count(*) as error_count FROM logs WHERE level = 'ERROR' AND regexp_like(message, '\\bv[0-9]+\\.[0-9]+\\.[0-9]+\\b')"}
{"task": "Identify services with version references in log messages", "sql": "SELECT DISTINCT service FROM logs WHERE regexp_like(message, 'v[0-9]+\\.[0-9]+\\.[0-9]+')"}
{"task": "Find events where request paths contain version strings", "sql": "SELECT * FROM events WHERE regexp_like(path, '/v[0-9]+\\.[0-9]+\\.[0-9]+/')"}
{"task": "List all unique version patterns found in messages or paths", "sql": "SELECT DISTINCT regexp_matches(message, 'v[0-9]+\\.[0-9]+\\.[0-9]+') as version FROM logs WHERE regexp_like(message, 'v[0-9]+\\.[0-9]+\\.[0-9]+') UNION SELECT DISTINCT regexp_matches(path, '/v[0-9]+\\.[0-9]+\\.[0-9]+/') as version FROM events WHERE regexp_like(path, '/v[0-9]+\\.[0-9]+\\.[0-9]+/')"}
{"task": "Show log entries with version strings grouped by service", "sql": "SELECT service, message, ts FROM logs WHERE regexp_like(message, '\\bv[0-9]+\\.[0-9]+\\.[0-9]+\\b') ORDER BY service, ts"}
{"task": "Find events that have version numbers in both path and user_id is greater than 1000", "sql": "SELECT * FROM events WHERE regexp_like(path, '/v[0-9]+\\.[0-9]+\\.[0-9]+/') AND user_id > 1000"}
{"task": "Count occurrences of version patterns in logs and events combined", "sql": "SELECT 'logs' as source, count(*) FROM logs WHERE regexp_like(message, '\\bv[0-9]+\\.[0-9]+\\.[0-9]+\\b') UNION ALL SELECT 'events' as source, count(*) FROM events WHERE regexp_like(path, '/v[0-9]+\\.[0-9]+\\.[0-9]+/')"}
{"task": "Identify log messages with version strings that also contain error keywords", "sql": "SELECT message, ts FROM logs WHERE regexp_like(message, 'v[0-9]+\\.[0-9]+\\.[0-9]+') AND regexp_like(message, '(error|exception|failure)')"}
{"task": "Find the most recent version references in log messages within last 24 hours", "sql": "SELECT message, ts FROM logs WHERE regexp_like(message, '\\bv[0-9]+\\.[0-9]+\\.[0-9]+\\b') AND ts > now() - interval '24 hours' ORDER BY ts DESC LIMIT 10"}

